class Instruction:
    """Base class for instructions"""

    _ftype = "instruction"
    _obj_id_count = 0

    def _get_obj_id(self):
        self.__class__._obj_id_count += 1
        return f"{self._ftype}#{self.__class__._obj_id_count}"

    def _instruction_hash(self, generating) -> int:
        """
        generate a hash from the generating input

        :param generating: something hashable
        :returns: a valid hash
        """
        return hash(generating)

    @staticmethod
    def _get_itype_common_root(instruction_list: List[Instruction]) -> str:
        """
        get the common root amongst string that are subdividable by '.'

        :param instruction_list: a list of instructions to be processed
        :returns: the greatest common root amongst all instructions.
        """
        if len(instruction_list) == 0:
            return ""
        segments_list = [instr.itype.split(".") for instr in instruction_list]
        latest_parent_itype = ".".join(segment_overlap(*segments_list))
        return latest_parent_itype

    def __str__(self):
        return f"<{self.identifier}>"

    def __repr__(self):
        return f"<{self.identifier}>"

    def __len__(self) -> int:
        """
        Return the length of the instruction

        :returns: instruction length
        """
        return 1

    def __init__(self, *, itype=None):
        self._sort_key = None
        self._itype = itype
        self._obj_id = self._get_obj_id()
        self._protected = True

    def __init_subclass__(cls, ftype: str):
        """
        init the subclass.

        :param ftype: the functional type of the subclass
        """
        ftype = ftype.replace(".", ":")
        cls._obj_id_count = 0
        cls._ftype += f".{ftype}"

    def __enter__(self):
        """
        enter an environment, where the write-protection is lifted
        """
        self._protected = False
        return self

    def __exit__(self, exc_type, exc_val, exc_tb):
        """
        exit the environment for write access, protection reenabled
        """
        self._protected = True

    def checksum(self) -> int:
        """
        Get a checksum object that can be fed to a hash function.
        Used to identify instructions being identical.
        """
        test_tuple = (
            self.identifier,
            self._itype,
            self._ftype,
        )
        return self._instruction_hash(test_tuple)

    @property
    def identifier(self) -> str:
        """
        get a unique identifier for the instruction.

        This identifier is typically composed from the ftype and a
        number that increases within the subclass
        :returns: identifier
        """
        return self._obj_id

    @property
    def instructions(self):
        """
        Iterate among the instructions. No offsets or anything applied, not recursion.
        """
        yield self

    # pylint: disable=unused-argument
    def unpack(self, recursive: bool | int = True, environment=None):
        """
        Unpacking goes through the instructions but interprets them wrt an environment.

        If recursive is set to an integer, this is the level of recursion (0=no unpacking, only
        self). If recursive is set to true, there is no level assumed an infinite unpacking is
        performed (default).
        Environments provide offsets, local definitions and special groupings.

        :param environment: optional environment.
        """
        for is_leaf, ref, ref_env in self.walk(
            recursive=recursive,
            environment=environment,
            include_groups=False,
        ):
            if is_leaf:
                yield ref.apply_environment(ref_env)

    def walk(
        self,
        environment=None,
        recursive: bool | int = True,
        include_groups=True,
    ):
        """
        walk the instruction tree. A generator that yields information on
        self, the environment and a flag whether it is a leaf
        """
        if environment is None:
            environment = InstructionEnvironment()
        if isinstance(recursive, int):
            if recursive == 0:
                return
        yield True, self, environment

    def to_dict(self, *keys, defaults: dict | None = None):
        """get a dictionary from keys, filled with the values"""
        raise NotImplementedError("Must be implemented in subclass")

    # pylint: enable=unused-argument

    @property
    def itype(self):
        """access read-only attribute itype"""
        return self._itype

    @property
    def ftype(self):
        """property for class level ftype attribute"""
        return self.__class__._ftype

    @property
    def sort_key(self):
        """access protected sort key attribute"""
        if self._sort_key is None:
            self._sort_key = self._get_sort_key()
        return self._sort_key

    def update_sort_key(self, function=None):
        """update the sort key"""
        self._sort_key = self._get_sort_key(function=function)

    def _get_default_sort_key(self):
        return tuple()

    def _get_sort_key(self, function=None):
        """get a sort key for the instruction, use default function if none is
        given"""
        if function is None:
            return self._get_default_sort_key()
        return function(self)

    def is_subtype(self, itype):
        """check if this instruction is a subtype of a reference.
        Returns true if this instruction's type can be derived from or is equal
        to the reference, i.e. the overlap of the instruction type is exactly
        the reference (which has at most the same length but all segments are
        identical)"""
        if isinstance(itype, Instruction):
            itype = itype.itype
        overlap = segment_overlap(*[self.itype.split("."), itype.split(".")])
        return overlap == itype.split(".")

    def __gt__(self, other):
        return self.itype > other.itype

    def __eq__(self, other):
        return self.itype == other.itype

    def __deepcopy__(self, memo=None):
        raise NotImplementedError("subclasses must implement this method")

    def deepcopy(self, memo=None):
        """
        Create a proper deep copy of the object.
        To ensure compatibility with traditional copy.copy, I go with a dict of
        weakref.refs instead of using weakref.WeakValueDictionary. Keep in mind
        that weakref.ref objects must be called to be properly referenced.
        """
        if memo is None:
            memo = {}
        # keep the linter happy...
        # pylint: disable=unnecessary-dunder-call
        return self.__deepcopy__(memo=memo)
        # pylint: enable=unnecessary-dunder-call

    def _apply_environment(
        self,
        environment: InstructionEnvironment,
        memo: dict,
    ) -> Instruction:
        """actually apply the environment"""
        raise NotImplementedError("Must be implemented in subclass")

    def apply_environment(
        self,
        environment: InstructionEnvironment | None = None,
        *,
        memo=None,
    ) -> Instruction:
        """
        Apply an environment to the instruction. User call, handles memo and environment initialization.
        """
        if environment is None:
            environment = InstructionEnvironment()
        if memo is None:
            memo = {}
        if (id(environment), id(self)) in memo:
            if (memorized := memo[(id(environment), id(self))]()) is not None:
                return memorized
        env_applied = self._apply_environment(environment, memo=memo)
        memo[(id(environment), id(self))] = weakref.ref(env_applied)
        return env_applied


