class GenericInstruction(Instruction, ftype="generic"):
    """Generic instruction.

    At this point the params dictionary is introduced. Multiple aliases are
    supported for flexible entry access without creating duplicates.
    """

    _alias: dict[str, str] = {}

    def __init__(self, itype=None, **params):
        if itype is None:
            itype = self.ftype
        super().__init__(itype=itype)
        # itype of generic instructions is by default the ftype
        self._params = params

    def __gt__(self, other):
        return self.sort_key > other.sort_key

    def __eq__(self, other):
        return self.sort_key == other.sort_key

    def _get_default_sort_key(self):
        return tuple(self.values())

    def keys(self):
        """dict like call to keys"""
        yield from self._params.keys()

    def items(self):
        """dict like call to items"""
        yield from self._params.items()

    def values(self):
        """dict like call to values"""
        yield from self._params.values()

    def __getitem__(self, key):
        if key in self._params:
            return self._params[key]
        return self._from_alias(key)

    def __setitem__(self, key, value):
        self.set(key, value)

    @classmethod
    def set_alias(cls, alias, reference):
        """add an alias to the class"""
        cls._alias[alias] = reference

    def checksum(self):
        test_tuple = (
            *super().checksum(),
            tuple(self.params),
        )
        return test_tuple

    @property
    def params(self):
        """access values as list"""
        return tuple(self.values())

    def get(self, *in_args):
        """mimic the get behaviour of dicts"""
        match in_args:
            case (key, default):
                if key in self._params:
                    return self._params[key]
                try:
                    return self._from_alias(key)
                except KeyError:
                    return default
                return default
            case (key,):
                if key in self._params:
                    return self._params[key]
                return self._from_alias(key)
            case _:
                raise ValueError(
                    "get requires a key and an optional default value to return"
                )

    def set(self, key, value):
        """set a value, consider protection"""
        if self._protected:
            raise ValueError(
                f"cannot access protected value of key '{key}' for writing"
            )
        self._params[key] = value

    def to_dict(self, *keys, defaults: dict | None = None):
        """get a dictionary from keys, filled with the values"""
        if defaults is None:
            defaults = {}
        # check params first, then check defaults, return None for miss
        data_dict = {}  # _PartialFormatDict
        if keys:
            data_dict.update(
                {key: self.get(key, defaults.get(key, None)) for key in keys}
            )
        else:
            data_dict.update(
                {
                    key: self.get(key, defaults.get(key, None))
                    for key in self.keys()
                }
            )
        return data_dict

    def to_tuple(self, *keys, defaults: dict | None = None):
        """get a data tuple from keys in the order the keys are requested"""
        if defaults is None:
            defaults = {}
        # check params first, then check defaults, return None for miss
        if keys:
            return tuple(
                self.get(key, defaults.get(key, None)) for key in keys
            )
        return tuple(
            self.get(key, defaults.get(key, None)) for key in self.keys()
        )

    def _from_alias(self, key):
        print(f"look up potential alias {key} in {self.__class__.__name__}")
        if key in self.__class__._alias:
            # don't call self._params here, so alias can chain
            return self[self.__class__._alias[key]]
        raise KeyError(f"Key '{key}' not found in dict nor alias map")

    def __deepcopy__(self, memo=None):
        if memo is None:
            memo = {}
        if id(self) in memo:
            return memo[id(self)]()  # beware, must be called due to weakref
        copied = self.__class__.from_dict(self._params)
        memo[id(self)] = weakref.ref(copied)
        return copied

    @classmethod
    def from_dict(cls, params):
        """
        generate a new class instance from a dictionary.
        Consider renaming here
        """
        return cls(**params)


class KeyMapInstruction(GenericInstruction, ftype="kmap"):
    """Represents an Expression"""

    def _apply_environment(
        self,
        environment: InstructionEnvironment,
        memo: dict,
    ) -> Instruction:
        """actually apply the environment"""
        modified_params = {}
        for key, val in self._params.items():
            if isinstance(val, InstructionVariable):
                if val.name in environment:
                    modified_params[key] = environment[val.name] | val
                else:
                    modified_params[key] = val
            else:
                modified_params[key] = val
        return self.__class__.from_dict(modified_params)


